#!/usr/bin/env tsx
/**
 * Update exam_page_url for a university in kakomon_universities.
 *
 * Usage:
 *   ./scripts/with-env.sh npx tsx scripts/update-exam-url.ts --university kobe --url "https://..."
 *   ./scripts/with-env.sh npx tsx scripts/update-exam-url.ts --university kobe --url "https://..." --dry-run
 */

import { createClient } from "@supabase/supabase-js";

function getArg(name: string): string | null {
  const idx = process.argv.indexOf(name);
  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
  return null;
}

const university = getArg("--university");
const url = getArg("--url");
const dryRun = process.argv.includes("--dry-run");

if (!university || !url) {
  console.error(
    "Usage: npx tsx scripts/update-exam-url.ts --university <id> --url <url> [--dry-run]"
  );
  process.exit(1);
}

const supabase = createClient(
  process.env.SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

// Verify university exists
const { data: uni, error: fetchErr } = await supabase
  .from("kakomon_universities")
  .select("id, name, exam_page_url")
  .eq("id", university)
  .single();

if (fetchErr || !uni) {
  console.error(`University not found: ${university}`);
  process.exit(1);
}

console.log(`University: ${uni.id} (${uni.name})`);
console.log(`  Current URL: ${uni.exam_page_url || "(null)"}`);
console.log(`  New URL:     ${url}`);

if (uni.exam_page_url === url) {
  console.log("  → Already up to date. No change needed.");
  process.exit(0);
}

if (dryRun) {
  console.log("  → Dry run. No changes made.");
  process.exit(0);
}

const { error: updateErr } = await supabase
  .from("kakomon_universities")
  .update({ exam_page_url: url })
  .eq("id", university);

if (updateErr) {
  console.error(`Failed to update: ${updateErr.message}`);
  process.exit(1);
}

console.log("  → Updated successfully.");

